.ca__s{flex:0 0 80%;scroll-snap-align:start;display:grid;place-items:center;height:140px;border:1px solid #d4d4d4;border-radius:12px;background:#fafafa;font:700 18px system-ui,sans-serif}
/* interaction */
.ca__n{display:flex;gap:8px;margin-top:8px}.ca__b{width:44px;height:44px;border:1px solid #0a0a0a;border-radius:50%;background:#fff;font-size:22px;line-height:1;cursor:pointer}.ca__b:disabled{opacity:.4;cursor:not-allowed}.ca__b:focus-visible{outline:2px solid #1d4ed8;outline-offset:2px}

code.js:
document.querySelectorAll('.ca').forEach(ca => {
  const view = ca.querySelector('.ca__v'), [prev, next] = ca.querySelectorAll('.ca__b');
  const slide = () => view.querySelector('.ca__s').getBoundingClientRect().width + 12;
  const calm = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const go = dir => view.scrollBy({ left: dir * slide(), behavior: calm ? 'auto' : 'smooth' });
  const sync = () => { prev.disabled = view.scrollLeft < 4; next.disabled = view.scrollLeft + view.clientWidth >= view.scrollWidth - 4; };
  prev.addEventListener('click', () => go(-1)); next.addEventListener('click', () => go(1));
  view.addEventListener('scroll', sync, { passive: true });
  view.addEventListener('keydown', e => {
    if (e.key === 'ArrowRight') { e.preventDefault(); go(1); } else if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); }
  });
  sync();
});
